// Pseudo: toggle ingestion throttle flag in SSM Parameter Store
import { SSMClient, PutParameterCommand } from "@aws-sdk/client-ssm";
const client = new SSMClient({ region: "us-east-1" });
async function throttleFlag(on) {
  await client.send(new PutParameterCommand({ Name: "/ingest/throttle", Value: on ? "true" : "false", Type: "String", Overwrite: true }));
}
```

